#include <iostream>
#include <set>
using namespace std;

int main() {
    set<int> s;
    s.insert(3); s.insert(1); s.insert(4); s.insert(1);
    for (int x : s) cout << x << " ";
    cout << endl;
    cout << s.count(3) << endl;
    auto it = s.lower_bound(2);
    cout << *it << endl;
    return 0;
}

#include <iostream>
#include <map>
using namespace std;

int main() {
    map<string, int> mp;
    mp["apple"] = 3;
    mp["banana"] = 5;
    mp["apple"]++;
    for (auto& [k, v] : mp)
        cout << k << ": " << v << endl;
    return 0;
}

#include <iostream>
#include <unordered_map>
using namespace std;

int main() {
    unordered_map<string, int> cnt;
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) {
        string s;
        cin >> s;
        cnt[s]++;
    }
    for (auto& [k, v] : cnt)
        cout << k << " " << v << endl;
    return 0;
}
